import numpy as np
import pandas as pd
from datetime import datetime
# Constants
DATE_FORMAT = '%Y-%m-%d %H:%M:%S'

def task_func(result):
    def _extract_from_user_values(obj):
        if obj is None:
            return []

        if isinstance(obj, pd.DataFrame):
            return obj["from_user"].to_numpy() if "from_user" in obj.columns else []

        if isinstance(obj, pd.Series):
            if obj.name == "from_user":
                return obj.to_numpy()
            if "from_user" in obj.index:
                return np.asarray([obj.loc["from_user"]])
            return []

        if isinstance(obj, dict):
            return obj.get("from_user", [])

        if isinstance(obj, (list, tuple)):
            values = []
            for item in obj:
                if isinstance(item, dict) and "from_user" in item:
                    values.append(item["from_user"])
            return values

        try:
            return obj["from_user"]
        except Exception:
            return []

    def _to_1d_list(values):
        if values is None:
            return []

        if np.isscalar(values):
            return [values]

        if isinstance(values, np.ndarray) and values.ndim == 0:
            return [values.item()]

        return list(np.asarray(values).ravel())

    raw_values = _extract_from_user_values(result)
    values_list = _to_1d_list(raw_values)

    if len(values_list) == 0:
        current_time = datetime.now().strftime(DATE_FORMAT)
        return pd.Series(
            {
                "mean": np.nan,
                "median": np.nan,
                "min": np.nan,
                "max": np.nan,
                "std": np.nan,
                "current_time": current_time,
            }
        )

    for value in values_list:
        if isinstance(value, (bool, np.bool_)) or not isinstance(
            value, (int, float, np.integer, np.floating)
        ):
            raise ValueError('The "from_user" values are not numeric.')

    numeric_values = np.asarray(values_list, dtype=float)
    numeric_values = numeric_values[~np.isnan(numeric_values)]

    if numeric_values.size == 0:
        mean = median = min_value = max_value = std = np.nan
    else:
        mean = float(np.mean(numeric_values))
        median = float(np.median(numeric_values))
        min_value = float(np.min(numeric_values))
        max_value = float(np.max(numeric_values))
        std = float(np.std(numeric_values, ddof=1)) if numeric_values.size > 1 else np.nan

    current_time = datetime.now().strftime(DATE_FORMAT)

    return pd.Series(
        {
            "mean": mean,
            "median": median,
            "min": min_value,
            "max": max_value,
            "std": std,
            "current_time": current_time,
        }
    )
